import React, {useEffect, useMemo, useState} from "react";
import {
    Alert,
    Button,
    Chip,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    Stack,
    TextField,
    Typography,
} from "@mui/material";
import AddBusinessOutlinedIcon from "@mui/icons-material/AddBusinessOutlined";
import BlockOutlinedIcon from "@mui/icons-material/BlockOutlined";
import DeleteOutlineIcon from "@mui/icons-material/DeleteOutline";
import EditOutlinedIcon from "@mui/icons-material/EditOutlined";
import LockOpenOutlinedIcon from "@mui/icons-material/LockOpenOutlined";
import LaunchOutlinedIcon from "@mui/icons-material/LaunchOutlined";
import {GridActionsCellItem, GridColDef, GridRowParams} from "@mui/x-data-grid";
import {toast} from "react-toastify";
import {AuthUser, Firm, UpsertFirm, UserRole} from "../../models/auth";
import {
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
    StyledDataGrid,
    Surface,
} from "../../ui/commonStyled/commonStyled";
import CoreButton from "../../ui/buttons/coreButton";
import Loader from "../../ui/loader/loader";
import {getApiErrorMessage} from "../../api/errors";
import {
    useCreateFirmMutation,
    useDeleteFirmMutation,
    useGetFirmUsersQuery,
    useGetFirmsQuery,
    useUpdateFirmAccessMutation,
    useUpdateFirmMutation,
} from "./firmsApi";
import {useAuth} from "../../auth/AuthContext";

const emptyDraft: UpsertFirm = {name: "", address: ""};

const roleLabels: Record<UserRole, string> = {
    employee: "Сотрудник",
    company_admin: "Администратор компании",
    super_admin: "Администратор системы",
};

const FirmsManagement = () => {
    const {user: currentUser, switchFirm} = useAuth();
    const {data: firms = [], isLoading} = useGetFirmsQuery();
    const [createFirm, {isLoading: isCreating}] = useCreateFirmMutation();
    const [updateFirm, {isLoading: isUpdating}] = useUpdateFirmMutation();
    const [updateFirmAccess, {isLoading: isUpdatingAccess}] = useUpdateFirmAccessMutation();
    const [deleteFirm] = useDeleteFirmMutation();
    const [editingFirm, setEditingFirm] = useState<Firm | null>(null);
    const [selectedFirmId, setSelectedFirmId] = useState<number | null>(null);
    const [draft, setDraft] = useState<UpsertFirm>(emptyDraft);
    const [dialogOpen, setDialogOpen] = useState(false);

    const selectedFirm = useMemo(
        () => firms.find((firm) => firm.id === selectedFirmId) ?? null,
        [firms, selectedFirmId],
    );
    const {
        data: firmUsers = [],
        isFetching: isUsersLoading,
        isError: isUsersError,
    } = useGetFirmUsersQuery(selectedFirmId ?? 0, {skip: selectedFirmId === null});

    useEffect(() => {
        if (!firms.length) {
            setSelectedFirmId(null);
            return;
        }

        if (selectedFirmId === null || !firms.some((firm) => firm.id === selectedFirmId)) {
            setSelectedFirmId(firms[0].id);
        }
    }, [firms, selectedFirmId]);

    const openCreate = () => {
        setEditingFirm(null);
        setDraft(emptyDraft);
        setDialogOpen(true);
    };

    const openEdit = (firm: Firm) => {
        setEditingFirm(firm);
        setDraft({name: firm.name, address: firm.address});
        setDialogOpen(true);
    };

    const save = async () => {
        try {
            if (editingFirm) {
                await updateFirm({id: editingFirm.id, body: draft}).unwrap();
            } else {
                await createFirm(draft).unwrap();
            }
            toast.success(editingFirm ? "Компания обновлена" : "Компания создана");
            setDialogOpen(false);
        } catch (error) {
            toast.error(getApiErrorMessage(error, "Не удалось сохранить компанию"));
        }
    };

    const changeAccess = async (firm: Firm) => {
        const action = firm.isBlocked ? "восстановить доступ" : "заблокировать";
        const details = firm.isBlocked
            ? "Пользователи снова смогут войти и продолжить работу."
            : "Все пользователи компании немедленно потеряют доступ к программе.";

        if (!window.confirm(`Вы уверены, что хотите ${action} для компании «${firm.name}»?\n\n${details}`)) {
            return;
        }

        try {
            await updateFirmAccess({id: firm.id, isBlocked: !firm.isBlocked}).unwrap();
            toast.success(firm.isBlocked ? "Доступ компании восстановлен" : "Компания заблокирована");
        } catch (error) {
            toast.error(getApiErrorMessage(error, "Не удалось изменить доступ компании"));
        }
    };

    const remove = async (firm: Firm) => {
        if (!window.confirm(`Удалить компанию «${firm.name}» и её пользователей? Это действие нельзя отменить.`)) {
            return;
        }

        try {
            await deleteFirm(firm.id).unwrap();
            toast.success("Компания удалена");
        } catch (error) {
            toast.error(getApiErrorMessage(error, "Не удалось удалить компанию"));
        }
    };

    const companyColumns: GridColDef<Firm>[] = [
        {field: "name", headerName: "Компания", minWidth: 220, flex: 1},
        {field: "address", headerName: "Адрес", minWidth: 240, flex: 1},
        {
            field: "isBlocked",
            headerName: "Доступ",
            width: 140,
            renderCell: (params) => params.value
                ? <Chip size="small" color="error" label="Заблокирована"/>
                : <Chip size="small" color="success" variant="outlined" label="Активна"/>,
        },
        {field: "activeUserCount", headerName: "Пользователей", width: 130},
        {field: "employeeCount", headerName: "Сотрудников", width: 125},
        {field: "companyAdminCount", headerName: "Админов", width: 100},
        {
            field: "actions",
            type: "actions",
            width: 190,
            getActions: (params: GridRowParams<Firm>) => [
                <GridActionsCellItem
                    key="open"
                    icon={<LaunchOutlinedIcon/>}
                    label="Открыть CRM компании"
                    disabled={params.row.isBlocked}
                    onClick={() => switchFirm(params.row.id)}
                    showInMenu
                />,
                <GridActionsCellItem
                    key="edit"
                    icon={<EditOutlinedIcon/>}
                    label="Редактировать"
                    onClick={() => openEdit(params.row)}
                />,
                <GridActionsCellItem
                    key="access"
                    icon={params.row.isBlocked ? <LockOpenOutlinedIcon/> : <BlockOutlinedIcon/>}
                    label={params.row.isBlocked ? "Восстановить доступ" : "Заблокировать"}
                    disabled={
                        isUpdatingAccess ||
                        params.row.isRequired ||
                        (!params.row.isBlocked && params.row.id === currentUser?.firmId)
                    }
                    onClick={() => changeAccess(params.row)}
                />,
                <GridActionsCellItem
                    key="delete"
                    icon={<DeleteOutlineIcon/>}
                    label="Удалить"
                    disabled={params.row.isRequired || params.row.id === currentUser?.firmId}
                    onClick={() => remove(params.row)}
                />,
            ],
        },
    ];

    const userColumns: GridColDef<AuthUser>[] = [
        {field: "name", headerName: "Имя", minWidth: 180, flex: 1},
        {field: "email", headerName: "Email", minWidth: 220, flex: 1},
        {
            field: "role",
            headerName: "Роль",
            minWidth: 220,
            valueFormatter: (params) => roleLabels[params.value as UserRole] || params.value,
        },
    ];

    if (isLoading) {
        return <Loader/>;
    }

    return (
        <MainDiv>
            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>Компании</PageTitle>
                    <PageSubtitle>
                        Список компаний и их пользователей. Блокировка немедленно закрывает доступ всем
                        пользователям выбранной компании, восстановление возвращает его без потери данных.
                    </PageSubtitle>
                </PageTitleGroup>
                <CoreButton
                    muiType="success"
                    text="Добавить компанию"
                    leftIcon={<AddBusinessOutlinedIcon/>}
                    onClick={openCreate}
                />
            </PageHeader>

            <Surface>
                <StyledDataGrid
                    autoHeight
                    rows={firms}
                    columns={companyColumns}
                    pageSizeOptions={[25, 50]}
                    onRowClick={(params) => setSelectedFirmId(Number(params.id))}
                    rowSelectionModel={selectedFirmId === null ? [] : [selectedFirmId]}
                    onRowSelectionModelChange={(selection) => {
                        if (selection.length) {
                            setSelectedFirmId(Number(selection[0]));
                        }
                    }}
                />
            </Surface>

            <Surface style={{marginTop: 18}}>
                {selectedFirm ? (
                    <Stack spacing={2}>
                        <Stack
                            direction={{xs: "column", sm: "row"}}
                            spacing={1}
                            alignItems={{xs: "flex-start", sm: "center"}}
                            justifyContent="space-between"
                        >
                            <div>
                                <Typography variant="h6" fontWeight={750}>
                                    Пользователи: {selectedFirm.name}
                                </Typography>
                                <Typography variant="body2" color="text.secondary">
                                    {selectedFirm.activeUserCount} активных учётных записей
                                </Typography>
                            </div>
                            <Stack direction="row" spacing={1} alignItems="center">
                                <Button
                                    variant="contained"
                                    startIcon={<LaunchOutlinedIcon/>}
                                    disabled={selectedFirm.isBlocked}
                                    onClick={() => switchFirm(selectedFirm.id)}
                                >
                                    Открыть CRM компании
                                </Button>
                                <Chip
                                    color={selectedFirm.isBlocked ? "error" : "success"}
                                    variant={selectedFirm.isBlocked ? "filled" : "outlined"}
                                    label={selectedFirm.isBlocked ? "Доступ заблокирован" : "Доступ разрешён"}
                                />
                            </Stack>
                        </Stack>
                        {isUsersError ? (
                            <Alert severity="error">Не удалось загрузить пользователей компании.</Alert>
                        ) : (
                            <StyledDataGrid
                                autoHeight
                                loading={isUsersLoading}
                                rows={firmUsers}
                                columns={userColumns}
                                pageSizeOptions={[25, 50]}
                                disableRowSelectionOnClick
                            />
                        )}
                    </Stack>
                ) : (
                    <Alert severity="info">Выберите компанию, чтобы посмотреть её пользователей.</Alert>
                )}
            </Surface>

            <Dialog open={dialogOpen} onClose={() => setDialogOpen(false)} fullWidth maxWidth="sm">
                <DialogTitle>{editingFirm ? "Редактирование компании" : "Новая компания"}</DialogTitle>
                <DialogContent sx={{display: "grid", gap: 2, paddingTop: "12px !important"}}>
                    <TextField
                        required
                        label="Название"
                        value={draft.name}
                        disabled={editingFirm?.isRequired}
                        onChange={(event) => setDraft({...draft, name: event.target.value})}
                    />
                    <TextField
                        label="Адрес"
                        value={draft.address}
                        onChange={(event) => setDraft({...draft, address: event.target.value})}
                    />
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setDialogOpen(false)}>Отмена</Button>
                    <Button
                        variant="contained"
                        onClick={save}
                        disabled={isCreating || isUpdating || !draft.name.trim()}
                    >
                        Сохранить
                    </Button>
                </DialogActions>
            </Dialog>
        </MainDiv>
    );
};

export default FirmsManagement;
